#pragma once
/// @file canopy_clustering.hpp
/// @brief Checked deterministic Euclidean canopies, actual construction traces and pair coverage.
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <limits>
#include <set>
#include <stdexcept>
#include <utility>
#include <vector>
namespace datamunge::algorithms {
/// @brief Owned canopy centre index and loose-radius member indices.
/// Members generated by canopy_clustering() are unique, ascending original indices.
/// Overlap is permitted. Removing a point from seed eligibility does not remove it
/// from subsequent membership searches. The default centre is zero, without points.
/// @par Example
/// @code
/// const auto c=dm::algorithms::canopy_clustering({{0},{1},{2},{3}},2.5,1.5);
/// std::print("{} {}\n",c[0].center,c[0].members); // 0 [0, 1, 2]
/// @endcode
/// @see canopy_clustering(), canopy_coverage()
struct Canopy {
  std::size_t center=0; ///< Original point index selected as this canopy's seed.
  std::vector<std::size_t> members; ///< Owned original point indices within the strict loose radius.
};
/// @brief One actual seed-to-point distance evaluation and its resulting decisions.
/// already_removed describes eligibility before this canopy started, not membership.
/// newly_removed includes the selected seed itself even when tight radius is zero.
/// Flags are from the shared kernel; they are not reconstructed from final canopies.
/// @par Example
/// @code
/// const auto t=dm::algorithms::canopy_clustering_trace({{0},{1}},2,1);
/// std::print("{} {}\n",t.visits[1].member,t.visits[1].within_tight); // true false
/// @endcode
/// @see CanopyTrace
struct CanopyVisit {
  std::size_t canopy=0; ///< Zero-based canopy index, in seed creation order.
  std::size_t point=0; ///< Original point index evaluated in this visit.
  double distance=0; ///< Computed Euclidean distance; may be infinity if not representable.
  bool already_removed=false; ///< Point was ineligible to seed before this canopy.
  bool member=false; ///< Computed distance is strictly below the loose radius.
  bool within_tight=false; ///< Computed distance is strictly below the tight radius.
  bool newly_removed=false; ///< Seed selection or this tight test newly consumed the point.
};
/// @brief Actual seed-pool transition for one complete canopy construction.
/// Vector position is the corresponding canopy id. newly_removed is ascending and
/// includes the selected seed, so every step consumes at least one point even at t2=0.
/// Visit offsets delimit this step's full original-index-order distance scan.
/// @par Example
/// @code
/// const auto t=dm::algorithms::canopy_clustering_trace({{0},{1},{2},{3}},2.5,1.5);
/// std::print("{} {}\n",t.steps[0].newly_removed,t.steps[0].remaining_after); // [0, 1] 2
/// @endcode
/// @see CanopyTrace
struct CanopyStep {
  std::size_t remaining_before=0; ///< Eligible seeds before selecting this centre.
  std::size_t remaining_after=0; ///< Eligible seeds after the complete canopy scan.
  std::vector<std::size_t> newly_removed; ///< Original indices consumed for the first time here.
  std::size_t visit_begin=0; ///< First visit index in the owning trace.
  std::size_t visit_count=0; ///< Actual evaluations in this step, equal to point_count.
};
/// @brief Owned result and actual Euclidean canopy construction provenance.
/// Inputs are not retained. Each of m seeds scans all n original points, including
/// previously consumed seeds: distance_evaluations=n*m, coordinate_differences=n*m*d.
/// Ordinary canopy_clustering() omits visits/steps. A trace needs O(n*m) additional
/// storage, with no replay or shared mutable state. Empty points give empty records.
/// @par Example
/// @code
/// const auto t=dm::algorithms::canopy_clustering_trace({{0},{1},{2},{3}},2.5,1.5);
/// std::print("{} {}\n",t.canopies.size(),t.distance_evaluations); // 2 8
/// @endcode
/// @see canopy_clustering_trace(), CanopyVisit, CanopyStep
struct CanopyTrace {
  std::vector<Canopy> canopies; ///< Actual owned canopies in increasing seed-index order.
  std::vector<CanopyStep> steps; ///< Actual eligibility transitions, one per canopy.
  std::vector<CanopyVisit> visits; ///< Actual distance decisions in canopy/point order.
  std::size_t point_count=0; ///< Number of original points.
  std::size_t dimension=0; ///< Common coordinate count, zero for empty or zero-width inputs.
  double loose_radius=0; ///< Effective positive finite membership radius.
  double tight_radius=0; ///< Effective finite removal radius in [0, loose_radius].
  std::size_t distance_evaluations=0; ///< Number of actual seed-to-point norm evaluations.
  std::size_t coordinate_differences=0; ///< Number of actual coordinate differences in those norms.
  std::size_t total_memberships=0; ///< Sum of the returned canopy member counts.
};
/// @brief Owned inverted memberships and unique unordered candidate pairs.
/// point_canopies[i] contains ascending canopy ids that include point i. shared_pairs
/// is lexicographically sorted with each first id smaller than its second id.
/// pair_visits counts all within-canopy pairs before deduplication, so it may exceed
/// shared_pairs.size(). These describe candidate retention, not a clustering accuracy
/// or speed guarantee. Copies are independent and own all indices.
/// @par Example
/// @code
/// const auto c=dm::algorithms::canopy_clustering({{0},{1},{2},{3}},2.5,1.5);
/// const auto s=dm::algorithms::canopy_coverage(4,c);
/// std::print("{} {}\n",s.total_memberships,s.shared_pairs.size()); // 7 6
/// @endcode
/// @see canopy_coverage()
struct CanopyCoverage {
  std::vector<std::vector<std::size_t>> point_canopies; ///< Owned canopy ids per original point.
  std::vector<std::pair<std::size_t,std::size_t>> shared_pairs; ///< Unique nonself pairs sharing any canopy.
  std::size_t total_memberships=0; ///< Sum of all member counts after duplicate validation.
  std::size_t overlapping_points=0; ///< Points appearing in more than one canopy.
  std::size_t uncovered_points=0; ///< Points appearing in no canopy.
  std::size_t pair_visits=0; ///< Number of actually considered within-canopy unordered pairs.
};
/// @brief Shared private checked Euclidean norms and canopy construction.
namespace detail {
/// @brief Euclidean norm with hypot accumulation to avoid squared-distance overflow/underflow.
/// Subtraction of extreme finite coordinates may overflow to infinity, meaning the
/// distance exceeds every permitted finite radius. Last-bit norm rounding can still
/// affect strict comparisons near a radius. No shared state, O(d) work, O(1) storage.
/// @param a Borrowed finite coordinate row.
/// @param b Borrowed finite row of exactly the same width.
/// @return Rounded nonnegative distance, possibly infinity when unrepresentable.
inline double canopy_dist(const std::vector<double>& a,const std::vector<double>& b) {
  double distance=0;
  for(std::size_t i=0;i<a.size();++i) distance=std::hypot(distance,a[i]-b[i]);
  return distance;
}
/// @brief Add a nonnegative canopy work or coverage count without wrapping.
/// @param value Counter to update, unchanged on overflow.
/// @param amount Increment.
/// @throws std::overflow_error Result exceeds size_t.
inline void canopy_add(std::size_t& value,std::size_t amount) {
  if(amount>std::numeric_limits<std::size_t>::max()-value) throw std::overflow_error("canopy: count overflow");
  value+=amount;
}
/// @brief Build the legacy all-points membership variant with optional actual records.
/// The lowest eligible index is the next seed. Selecting the seed consumes it even
/// at zero tight radius; this preserves the original increasing-index scan's outputs.
/// @tparam Record Whether to retain visits and seed-pool transitions.
/// @param points Borrowed rectangular finite coordinates, zero-width/empty permitted.
/// @param t1 Positive finite strict membership radius.
/// @param t2 Finite strict removal radius in [0,t1].
/// @param budget Whole-call distance cap; zero is unlimited.
/// @return Owned result and checked counts; ordinary mode has empty provenance vectors.
/// @throws std::invalid_argument Invalid radii, ragged rows or nonfinite coordinates.
/// @throws std::length_error The next distance would exceed a positive budget.
/// @throws std::overflow_error Actual work or membership counters exceed size_t.
template<bool Record>
inline CanopyTrace canopy_build(const std::vector<std::vector<double>>& points,double t1,double t2,std::size_t budget) {
  if(!std::isfinite(t1) || !std::isfinite(t2) || t1<=0 || t2<0 || t2>t1)
    throw std::invalid_argument("canopy: invalid radii");
  const auto n=points.size(),dimension=points.empty()?0:points.front().size();
  for(const auto& point:points) {
    if(point.size()!=dimension) throw std::invalid_argument("canopy: ragged points");
    for(double value:point) if(!std::isfinite(value)) throw std::invalid_argument("canopy: nonfinite coordinate");
  }
  CanopyTrace out;out.point_count=n;out.dimension=dimension;out.loose_radius=t1;out.tight_radius=t2;
  std::vector<char> removed(n,0);std::size_t remaining=n;
  for(std::size_t i=0;i<n;++i) {
    if(removed[i]) continue;
    Canopy canopy;canopy.center=i;
    CanopyStep step;
    if constexpr(Record) {step.remaining_before=remaining;step.visit_begin=out.visits.size();step.newly_removed.push_back(i);}
    removed[i]=1;--remaining;
    for(std::size_t j=0;j<n;++j) {
      if(budget && out.distance_evaluations>=budget) throw std::length_error("canopy: distance budget exceeded");
      canopy_add(out.distance_evaluations,1);canopy_add(out.coordinate_differences,dimension);
      const double distance=canopy_dist(points[i],points[j]);
      const bool before=removed[j] && j!=i,member=distance<t1,tight=distance<t2;
      const bool newly=!before && (j==i || tight);
      if(member) {canopy.members.push_back(j);canopy_add(out.total_memberships,1);}
      if(tight && !removed[j]) {
        removed[j]=1;--remaining;
        if constexpr(Record) step.newly_removed.push_back(j);
      }
      if constexpr(Record) out.visits.push_back({out.canopies.size(),j,distance,before,member,tight,newly});
    }
    if constexpr(Record) {step.remaining_after=remaining;step.visit_count=out.visits.size()-step.visit_begin;out.steps.push_back(std::move(step));}
    out.canopies.push_back(std::move(canopy));
  }
  return out;
}
} // namespace detail
/// @brief Deterministic Euclidean canopies with separate membership and seed eligibility.
/// Select the lowest eligible input index. Scan all original points, adding those
/// with distance<t1; selecting the seed and distance<t2 make points ineligible for
/// later seeding. Previously ineligible points still join later canopies. Both tests
/// are strict, equality is outside; t1=t2 is allowed, and t2=0 makes every point a seed.
/// Zero-width points have zero distance. Empty points return no canopies after radius
/// validation. Finite rectangular inputs are checked before accessing coordinates.
/// Hypot accumulation avoids squared-distance overflow/underflow, but not norm rounding.
/// This all-points Euclidean variant supplies no approximate metric/index or downstream
/// clustering. Nearby pairs are not universally retained merely because t1>=t2.
/// Inputs are borrowed, unchanged; result owns indices, no shared mutable state.
/// Work O(n*m*d+n*m), m<=n seeds and d coordinates; storage O(n+sum memberships).
/// @param points Rectangular finite numeric rows, empty/zero-width permitted; input order matters.
/// @param t1 Positive finite strict loose membership radius.
/// @param t2 Finite strict tight removal radius, 0<=t2<=t1.
/// @return Owned overlapping canopies, seeds and members in increasing original-index order.
/// @throws std::invalid_argument Invalid radii, ragged rows or nonfinite coordinates.
/// @throws std::overflow_error Work or membership counts exceed size_t.
/// @par Example
/// @code
/// const auto c=dm::algorithms::canopy_clustering({{0},{1},{2},{3}},2.5,1.5);
/// std::print("{} {}\n",c.size(),c[1].members); // 2 [0, 1, 2, 3]
/// @endcode
/// @par References
/// - A. McCallum, K. Nigam and L. H. Ungar (2000), Efficient Clustering of
///   High-Dimensional Data Sets with Application to Reference Matching, KDD, 169-178.
///   https://doi.org/10.1145/347090.347123 (restricted deterministic Euclidean variant).
/// @see canopy_clustering_trace(), canopy_coverage(), canopy_centers()
inline std::vector<Canopy> canopy_clustering(const std::vector<std::vector<double>>& points,double t1,double t2) {
  return detail::canopy_build<false>(points,t1,t2,0).canopies;
}
/// @brief Construct Euclidean canopies once and retain actual distances and pool transitions.
/// Same shared kernel and result as canopy_clustering(), without replay. A positive
/// whole-call budget throws before the excess distance evaluation; no partial result
/// is returned. Recording adds O(n*m) storage. Source coordinates are not retained.
/// Seed selection itself consumes a point, even when its tight-radius test is false
/// at t2=0; this distinction is visible in visit and step records.
/// @param points Borrowed rectangular finite rows; input-order policy matches canopy_clustering().
/// @param t1 Positive finite strict membership radius.
/// @param t2 Finite strict removal radius in [0,t1].
/// @param max_distance_evaluations Whole-call distance cap; zero (default) is unlimited.
/// @return Owned actual canopies, visit decisions, eligibility transitions and counters.
/// @throws std::invalid_argument Invalid radii, ragged rows or nonfinite coordinates.
/// @throws std::length_error Distance budget exceeded.
/// @throws std::overflow_error Work or membership counts exceed size_t.
/// @par Example
/// @code
/// const auto t=dm::algorithms::canopy_clustering_trace({{0},{1},{2},{3}},2.5,1.5,8);
/// std::print("{} {}\n",t.total_memberships,t.coordinate_differences); // 7 8
/// @endcode
/// @par References
/// - McCallum, Nigam and Ungar (2000). https://doi.org/10.1145/347090.347123
/// @see canopy_clustering(), CanopyTrace
inline CanopyTrace canopy_clustering_trace(const std::vector<std::vector<double>>& points,double t1,double t2,
    std::size_t max_distance_evaluations=0) {
  return detail::canopy_build<true>(points,t1,t2,max_distance_evaluations);
}
/// @brief Copy selected centre coordinates, checking only centre indices.
/// The helper does not compute distances or validate member lists, rectangularity or
/// finiteness. Arbitrary coordinate rows are copied in canopy order, including repeats;
/// copies own their storage independently of points/canopies. Work/storage is proportional
/// to the copied coordinates; inputs are borrowed and unchanged, no shared state.
/// @param points Borrowed coordinate rows, possibly empty or ragged.
/// @param canopies Borrowed records with every centre index within points.
/// @return Owned coordinate rows in canopy order; empty for no canopies.
/// @throws std::out_of_range A centre index is absent from points.
/// @par Example
/// @code
/// const std::vector<std::vector<double>> p{{0},{3}};
/// const auto c=dm::algorithms::canopy_clustering(p,1,1);
/// std::print("{}\n",dm::algorithms::canopy_centers(p,c)); // [[0], [3]]
/// @endcode
/// @see canopy_clustering(), Canopy
inline std::vector<std::vector<double>> canopy_centers(const std::vector<std::vector<double>>& points,
    const std::vector<Canopy>& canopies) {
  std::vector<std::vector<double>> centres;centres.reserve(canopies.size());
  for(const auto& c:canopies) {
    if(c.center>=points.size()) throw std::out_of_range("canopy_centers: invalid centre index");
    centres.push_back(points[c.center]);
  }
  return centres;
}
/// @brief Invert canopy memberships and enumerate unique unordered shared-canopy pairs.
/// Checks centre/member bounds and rejects duplicate members within a canopy, while
/// allowing unsorted members, repeated centres and overlap across canopies. Empty
/// canopies may leave points uncovered. Pair visits count each within-canopy unordered
/// pair before deduplication; a positive cap throws before an excess visit. Owned
/// inputs are never modified and no partial coverage is returned on exception.
/// For M memberships, V pair visits and U unique pairs, ordered-set insertion costs
/// O(V*log(U+1)); add per-canopy member sorting and O(point_count+M+U) output storage.
/// This is an explicit diagnostic enumeration, not a scalable spatial index.
/// @param point_count Number of indexed points, independent of coordinate values.
/// @param canopies Borrowed records with valid centre and unique in-range members.
/// @param max_pair_visits Whole-call before-deduplication pair cap; zero (default) is unlimited.
/// @return Owned point memberships, unique pairs, overlap/uncovered counts and actual pair visits.
/// @throws std::invalid_argument Out-of-range centre/member or duplicate within-canopy membership.
/// @throws std::length_error Pair-visit budget exceeded.
/// @throws std::overflow_error Membership or pair counters exceed size_t.
/// @par Example
/// @code
/// const auto c=dm::algorithms::canopy_clustering({{0},{1},{2},{3}},2.5,1.5);
/// const auto s=dm::algorithms::canopy_coverage(4,c,9);
/// std::print("{} {}\n",s.overlapping_points,s.pair_visits); // 3 9
/// @endcode
/// @see CanopyCoverage, canopy_clustering()
inline CanopyCoverage canopy_coverage(std::size_t point_count,const std::vector<Canopy>& canopies,
    std::size_t max_pair_visits=0) {
  CanopyCoverage out;out.point_canopies.resize(point_count);
  std::set<std::pair<std::size_t,std::size_t>> pairs;
  for(std::size_t id=0;id<canopies.size();++id) {
    const auto& canopy=canopies[id];
    if(canopy.center>=point_count) throw std::invalid_argument("canopy_coverage: invalid centre");
    auto members=canopy.members;std::sort(members.begin(),members.end());
    if(std::adjacent_find(members.begin(),members.end())!=members.end()) throw std::invalid_argument("canopy_coverage: duplicate member");
    for(auto point:members) if(point>=point_count) throw std::invalid_argument("canopy_coverage: invalid member");
    detail::canopy_add(out.total_memberships,members.size());
    for(auto point:members) out.point_canopies[point].push_back(id);
    for(std::size_t i=0;i<members.size();++i) for(std::size_t j=i+1;j<members.size();++j) {
      if(max_pair_visits && out.pair_visits>=max_pair_visits) throw std::length_error("canopy_coverage: pair budget exceeded");
      detail::canopy_add(out.pair_visits,1);pairs.emplace(members[i],members[j]);
    }
  }
  out.shared_pairs.assign(pairs.begin(),pairs.end());
  for(const auto& ids:out.point_canopies) {
    if(ids.empty()) ++out.uncovered_points;
    else if(ids.size()>1) ++out.overlapping_points;
  }
  return out;
}
} // namespace datamunge::algorithms
